#!/usr/bin/env bash
set -euo pipefail
# GENERATED by dag/gunbc/fleet_converge_emit.dag (gunbc.fleet_converge_emit). DO NOT HAND-EDIT.
# Thin-run: steady-state converge via gunbc converge --host (ConvergePlan in-process, EmitArtifactThenThinRun slice 2).
# Bootstrap: fresh-standup hosts only — category B pre-runtime (git-checkout / cargo-build / cp).

host_failed=0

gunbc converge --host "srv1" || host_failed=1
gunbc converge --host "srv2" || host_failed=1
# fresh-standup bootstrap (srv3 exemplar) — ONE orchestration intent tree.
checkout="$HOME/ctrl/third_party/gunbc"
ctrl_pin="$(bash "$HOME/ctrl/scripts/session-dashboard/container/read-gunbc-pin.sh" "$HOME/ctrl" 2>/dev/null || true)"
(cd "$checkout" && git fetch --prune origin) >/dev/null 2>&1 || true
(cd "$checkout" && git checkout --detach "$ctrl_pin") >/dev/null 2>&1 || true
mkdir -p "$HOME/.local/share/gunbc/pinned"
(cd "$checkout" && cargo build -p v1-compiler --release --bin gunbc) >/dev/null 2>&1 || true
cp "$HOME/ctrl/third_party/gunbc/target/release/gunbc" "$HOME/.local/share/gunbc/pinned/gunbc" >/dev/null 2>&1 || true
if [ -x "$HOME/.local/share/gunbc/pinned/gunbc" ]; then export GUNBC_ROOT=$HOME/.local/share/gunbc/pinned; fi
gunbc converge --host "srv3" || host_failed=1
exit "$host_failed"
